verus! {
    #[verifier::spec]
    fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> (result: Vec<T>) 
    requires
        // Ensure the index is within the valid range
        0 <= idx && idx <= arr.len(),
    ensures
        // The resulting array has length one greater than the original
        result.len() == arr.len() + 1,
        // Elements before the insertion index remain in the same order
        forall|j: usize| (j < idx ==> result[j] == arr[j]),
        // The element at the insertion index is the provided value
        result[idx] == value,
        // Elements after the insertion index are shifted right by one position
        forall|j: usize| (j + 1 < result.len() ==> (j >= idx ==> result[j + 1] == arr[j])),
    decreases
        arr.len(), // Decrease clause to ensure termination
    {
        // Create a new vector with the size of the original array plus one
        let mut result = Vec::with_capacity(arr.len() + 1);
        
        // Insert elements before the index
        for i in 0..idx {
            result.push(arr[i]);
        }
        
        // Insert the new value at the specified index
        result.push(value);
        
        // Insert elements after the index
        for i in idx..arr.len() {
            result.push(arr[i]);
        }
        
        result // Return the resulting array
    }
}